// And groups predicates with the AND operator between them.
func And(predicates ...predicate.Initiative) predicate.Initiative {
	return predicate.Initiative(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.Initiative) predicate.Initiative {
	return predicate.Initiative(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.Initiative) predicate.Initiative {
	return predicate.Initiative(sql.NotPredicates(p))
}
